        for p in setup_league:
            if isinstance(p, ActivePlayer):
                assert not p.is_trained_enough()
                assert p._last_enough_step == 0
                # step_passed < ONE_PHASE_STEP
                p.total_agent_step = ONE_PHASE_STEP * 0.99
